using LealInfoPDV;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json.Nodes;
static class Program {
 static void Check(bool yes,string msg){if(!yes)throw new Exception(msg);Console.WriteLine("PASS "+msg);}
 static object? Sql(string sql){using var db=Database.Open();using var q=db.CreateCommand();q.CommandText=sql;return q.ExecuteScalar();}
 static async Task<string> Grant(AngraSyncTransport transport,string role,bool other=false){
 using var http=new HttpClient();string url=Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_URL")!+"&audience="+Uri.EscapeDataString("angra-sync-ci:"+transport.DeviceId);using var req=new HttpRequestMessage(HttpMethod.Get,url);req.Headers.Authorization=new("Bearer",Environment.GetEnvironmentVariable("ACTIONS_ID_TOKEN_REQUEST_TOKEN"));var oidc=JsonNode.Parse(await (await http.SendAsync(req)).Content.ReadAsStringAsync())!;
 using var grantRequest=new HttpRequestMessage(HttpMethod.Post,AngraSyncTransport.Origin+"/sync/ci-grant");grantRequest.Headers.Authorization=new("Bearer",oidc["value"]!.ToString());grantRequest.Content=new StringContent(new JsonObject{["deviceId"]=transport.DeviceId,["role"]=role,["otherTenant"]=other^(Environment.GetEnvironmentVariable("ANGRA_QA_CHANNEL")=="003"),["publicKey"]=transport.PublicKey}.ToJsonString(),System.Text.Encoding.UTF8,"application/json");using var grant=await http.SendAsync(grantRequest);Check(grant.IsSuccessStatusCode,"GitHub OIDC grants isolated "+role+" test identity");return JsonNode.Parse(await grant.Content.ReadAsStringAsync())!["tenant"]!.ToString();
 }
 static async Task Benchmark(){Check(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true","isolated Windows timing");Database.Initialize();typeof(Auth).GetProperty("Current")!.SetValue(null,new UserSession(1,"QA","qa","ADMINISTRADOR","","",false));using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);using var transport=new AngraSyncTransport(Convert.ToBase64String(key.ExportPkcs8PrivateKey()));string tenant=await Grant(transport,"pdv");var timings=new JsonObject();async Task Measure(string name,Func<Task> action){var sw=System.Diagnostics.Stopwatch.StartNew();try{await action();timings[name+"_ok"]=true;}catch(Exception e){timings[name+"_ok"]=false;timings[name+"_error"]=e.Message;}timings[name+"_ms"]=sw.ElapsedMilliseconds;Console.WriteLine("TIMING "+name+" "+sw.ElapsedMilliseconds+" ms");}
 await Measure("status",async()=>{await transport.Call("/sync/status",new());});using(var pairing=new AngraPairing(new AngraSyncTransport(Convert.ToBase64String(key.ExportPkcs8PrivateKey())))){await Measure("generate_code",async()=>{Check(await pairing.Generate(),"code generated");});}
 using(var service=new AngraSyncService(transport,false)){service.UseTestTenant(tenant);await Measure("sync_initial",()=>service.Tick());await Measure("sync_warm",()=>service.Tick());}
 Directory.CreateDirectory("perf-evidence");File.WriteAllText("perf-evidence/timing.json",timings.ToJsonString());}
 static async Task Main(string[] args){
 if(args.Length>0&&args[0]=="benchmark"){await Benchmark();return;}
 bool verify=args.Length>0&&args[0]=="verify";
 if(verify){Directory.CreateDirectory(Database.AppFolder);File.Copy("qa/angra-sync/evidence/fixture.db",Database.DbPath,true);}
 Check(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true","disposable Windows only");Database.Initialize();
 if(!verify)Sql("INSERT INTO customers(name,document,phone) VALUES('BOB','QA-BOB','24999990000'); INSERT INTO suppliers(name) VALUES('FORNECEDOR QA'); INSERT INTO products(name,price,stock,active) VALUES('VIDRO QA',100,5,1);SELECT 1");
 using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);string privateKey=verify?JsonNode.Parse(File.ReadAllText("qa/angra-sync/evidence/sync-seed.json"))!["privateKey"]!.ToString():Convert.ToBase64String(key.ExportPkcs8PrivateKey());var transport=new AngraSyncTransport(privateKey);
 string tenant=verify?(await transport.Call("/sync/request-pdv",new()))["tenant"]!.ToString():await Grant(transport,"pdv");
 // Hold the real PDV receiver offline until Android has proved ENVIADO and persisted its outbox.
 if(verify){bool ready=false;for(int attempt=0;attempt<120&&!ready;attempt++){try{string? cursor=null;do{var page=await transport.Call("/sync/exchange",new(){["changes"]=new JsonArray(),["cursor"]=cursor});ready|=page["records"]!.AsArray().Any(x=>x?["payload"]?["name"]?.ToString()=="QA PDV PODE VOLTAR");cursor=page["cursor"]?.ToString()??"";}while(cursor!="");}catch(Exception e)when(e is IOException or HttpRequestException or System.Text.Json.JsonException){Console.WriteLine("WAIT transient HTTP while isolated PDV receiver remains stopped");}if(!ready)await Task.Delay(5000);}Check(ready,"Android sent project while Windows receiver was stopped; restart authorized by test marker");}
 using var service=new AngraSyncService(transport,false);service.UseTestTenant(tenant);await service.Tick();Check(service.Status.Contains("PDV CONECTADO"),service.Status);var store=service.Store!;if(verify){for(int i=0;i<3;i++)await service.Tick();Check(Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers WHERE name='CLIENTE TESTE APP'"))==1,"APP -> real SQLite exactly one contact");Check(Convert.ToString(Sql("SELECT phone FROM customers WHERE name='CLIENTE TESTE APP'"))=="24977770000","edited phone imported without duplicate");var imported=store.Links().Where(x=>x.Entity=="projects").Select(x=>(Link:x,Data:store.ReadLocal(x))).Single(x=>x.Data?["title"]?.ToString()=="PROJETO APP SYNC BOX");Check(imported.Data!["type"]!.ToString()=="Box de banheiro","generic box not transformed into window");var saved=GlassProjectStore.Load(imported.Link.LocalId!);Check(saved.Data.WidthMm==2000&&saved.Data.HeightMm==2000,"physical 2m x 2m preserved in PDV");Check(saved.Data.Quote.CustomerId>0,"real customer linked to generic project");Check(saved.Data.Quote.Price==100.50m&&saved.Data.Quote.ServiceValue==10m&&saved.Data.Quote.Discount==5m&&saved.Data.Quote.Addition==2m&&saved.Data.Quantity==2,"decimal BR budget and quantity preserved exactly");Check(saved.Data.Materials.Length==1&&saved.Data.Materials[0].Name=="VIDRO QA","official material linked without stock movement");var official=await transport.Call("/sync/exchange",new(){["changes"]=new JsonArray()});bool confirmed=false;while(true){confirmed|=official["records"]!.AsArray().Any(x=>x?["id"]?.ToString()==imported.Link.Id&&x?["officialId"]?.ToString()==imported.Link.LocalId&&x?["receivedByPdv"]?.GetValue<bool>()==true);string cursor=official["cursor"]?.ToString()??"";if(cursor=="")break;official=await transport.Call("/sync/exchange",new(){["changes"]=new JsonArray(),["cursor"]=cursor});}Check(confirmed,"current project revision RECEBIDO only after real SQLite import and photo download");string sha=imported.Data["photoAttachment"]!["sha256"]!.ToString();Check(File.Exists(AngraSyncService.PhotoPath(imported.Link.Id,sha)),"actual binary JPEG transferred Android -> HTTPS -> PDV");long count=Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers"));await service.Tick();await service.Tick();Check(count==Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers")),"reopen and retries do not duplicate");Check(Convert.ToInt64(Sql("SELECT COUNT(*) FROM cash_movements"))==0,"project/budget import creates no payment");Console.WriteLine("PASS REAL ANDROID HTTPS PDV END TO END");return;}var bob=store.Links().Single(x=>x.Entity=="clients"&&store.ReadLocal(x)?["name"]?.ToString()=="BOB");Check(bob.Revision>0,"BOB real SQLite uploaded to real HTTPS backend");long originalCount=Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers"));bool duplicateBlocked=false;try{store.ApplyRecord(new AngraLink("clients",Guid.NewGuid().ToString(),null,0,null,null,null,""),new JsonObject{["name"]=" bob ",["document"]="",["phone"]="24999990000"},null);}catch(InvalidOperationException){duplicateBlocked=true;}Check(duplicateBlocked&&Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers"))==originalCount,"ambiguous customer without document preserved for review without duplicate");
 using var otherKey=ECDsa.Create(ECCurve.NamedCurves.nistP256);var app=new AngraSyncTransport(Convert.ToBase64String(otherKey.ExportPkcs8PrivateKey()));await Grant(app,"app");
 Sql("UPDATE customers SET phone='LOCAL' WHERE name='BOB';SELECT 1");store.Prepare();var remote=bob.Baseline!.DeepClone().AsObject();remote["phone"]="REMOTE";var changed=await app.Call("/sync/exchange",new(){["changes"]=new JsonArray(new JsonObject{["entity"]="clients",["id"]=bob.Id,["baseRevision"]=bob.Revision,["operationId"]=Guid.NewGuid().ToString(),["payload"]=remote})});Check(changed["results"]![0]!["ok"]!.GetValue<bool>(),"other authorized actor edits actual HTTPS record");await service.Tick();Check(store.Link("clients",bob.Id).Conflict!=null&&Convert.ToString(Sql("SELECT phone FROM customers WHERE name='BOB'"))=="LOCAL","real revision conflict preserves local edit and remote version");store.Resolve("clients",bob.Id,false);await service.Tick();Sql("UPDATE customers SET phone='24999990000' WHERE name='BOB';SELECT 1");await service.Tick();
 var product=store.Links().First(x=>x.Entity=="materials");var blocked=await app.Call("/sync/exchange",new(){["changes"]=new JsonArray(new JsonObject{["entity"]="materials",["id"]=product.Id,["operationId"]=Guid.NewGuid().ToString(),["baseRevision"]=product.Revision,["payload"]=store.ReadLocal(product)})});Check(blocked["results"]![0]!["ok"]?.GetValue<bool>()!=true,"real backend rejects Android product/stock write");
 await Grant(app,"app",true);var isolated=await app.Call("/sync/exchange",new(){["changes"]=new JsonArray()});Check(!isolated["records"]!.AsArray().Any(x=>x?["id"]?.ToString()==bob.Id),"other tenant cannot see own BOB through actual HTTPS");
 // Upgrade scenario: an already imported legacy project has no pending receipt and no new payload revision.
 await Grant(app,"app");string legacyId=Guid.NewGuid().ToString();var legacyPayload=new JsonObject{["title"]="LEGACY RECEIPT QA",["type"]="Box de banheiro",["clientLocalId"]=bob.Id,["measures"]=new JsonArray(new JsonObject{["label"]="Largura",["value"]="2",["unit"]="m",["mm"]="2000"},new JsonObject{["label"]="Altura",["value"]="2",["unit"]="m",["mm"]="2000"})};var legacyResponse=await app.Call("/sync/exchange",new(){["changes"]=new JsonArray(new JsonObject{["entity"]="projects",["id"]=legacyId,["baseRevision"]=0,["operationId"]=Guid.NewGuid().ToString(),["payload"]=legacyPayload})});var legacyRecord=legacyResponse["results"]![0]!["record"]!.DeepClone();store.Apply(new JsonObject{["tenant"]=tenant,["records"]=new JsonArray(legacyRecord)});var legacyLink=store.Link("projects",legacyId);Check(legacyLink.LocalId!=null,"legacy project imported into actual Windows store");store.Save(legacyLink with{Pending=null});await service.Tick();Check(store.Link("projects",legacyId).Pending!=null,"same-revision legacy project schedules receipt without rewriting saved data");await service.Tick();Check(store.Link("projects",legacyId).Pending==null,"legacy receipt acknowledged through existing outbox");

long before=Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers"));await service.Tick();Check(Convert.ToInt64(Sql("SELECT COUNT(*) FROM customers"))==before,"retry no customer duplicate");Check(Convert.ToInt64(Sql("SELECT COUNT(*) FROM cash_movements"))==0,"sync no financial operation");Check(Convert.ToDecimal(Sql("SELECT stock FROM products WHERE name='VIDRO QA'"))==5,"stock unchanged");Check(Directory.GetFiles(Database.BackupFolder,"ANTES_ANGRA_SYNC_*.db").Length>0,"backup before additive migration");
 Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();string outdir="qa/angra-sync/evidence";Directory.CreateDirectory(outdir);File.Copy(Database.DbPath,Path.Combine(outdir,"fixture.db"),true);File.WriteAllText(Path.Combine(outdir,"sync-seed.json"),new JsonObject{["privateKey"]=privateKey,["deviceId"]=transport.DeviceId,["code"]=await service.Ticket()}.ToJsonString());File.WriteAllText(Path.Combine(outdir,"real-windows.json"),new JsonObject{["tenant"]=tenant,["bobId"]=bob.Id,["status"]=service.Status,["realHttps"]=true}.ToJsonString());
 }
}
